15	const plural = (count: number, one: string, many: string) => `${count} ${count === 1 ? one : many}`;
16	const VISIBLE = 3;
17	
18	export function groupRepeats(proposals: OpenProposal[]) {
19	  const groups = new Map<string, OpenProposal[]>();
20	  for (const proposal of proposals) {
21	    const key = proposal.kind === "transaction_create" ? `${proposal.title}|${proposal.detail}` : proposal.id;
22	    groups.set(key, [...(groups.get(key) ?? []), proposal]);
23	  }
24	  return [...groups.values()];
25	}
26	
27	function RepeatGroup({ proposals, locale }: { proposals: OpenProposal[]; locale?: string }) {
28	  const [pending, start] = useBusy();
29	  const [dismissed, setDismissed] = useState(false);
30	  const [error, setError] = useState<string>();
31	  if (dismissed) return <p role="status" className="my-3 text-sm text-muted-foreground">Dismissed {proposals.length} repeats. Nothing was changed.</p>;
32	  const dismiss = () => start(async () => {
33	    setError(undefined);
34	    try {
35	      const outcomes = await decideAgentProposals(proposals.map(proposal => proposal.id), "reject");
36	      const failed = outcomes.find(outcome => outcome.error);
37	      if (failed) setError(failed.error); else setDismissed(true);
38	    } catch { setError("Could not dismiss these. Try again."); }
39	  });
40	  return <details aria-label="Similar proposals" className="my-3 rounded-xl border border-ai-border bg-ai-soft/40 p-4">
41	    <summary className="cursor-pointer font-medium">{proposals.length} similar: {proposals[0].title}</summary>
42	    <p className="mt-2 text-sm text-muted-foreground">These look like the same purchase. Add only the ones that really happened.</p>
43	    {error && <p role="alert" className="mt-2 text-sm text-danger">{error}</p>}
44	    <button type="button" disabled={pending} onClick={dismiss} className="mt-2 min-h-9 rounded-lg border border-border px-4 text-sm hover:bg-muted disabled:opacity-50">Dismiss all {proposals.length}</button>
45	    {proposals.map(proposal => <IouCard key={proposal.id} id={proposal.id} initial={proposal} locale={locale} />)}
46	  </details>;
47	}
48	
49	export function WaitingForYouList({ proposals: all, review = { uncategorized: 0, findings: [] }, locale }: { proposals: OpenProposal[]; review?: HomeReview; locale?: string }) {
50	  const [filter, setFilter] = useState<Filter>();
51	  const [expanded, setExpanded] = useState(false);
52	  const recurring = all.filter(proposal => proposal.kind === "recurring_edit");
53	  const proposals = all.filter(proposal => proposal.kind !== "recurring_edit");
54	  const entries: { key: string; filter?: Filter; node: React.ReactNode }[] = [
55	    ...review.uncategorized > 0 ? [{ key: "uncategorized", node: <SummaryCard title={`${plural(review.uncategorized, "transaction needs", "transactions need")} a category`} detail="Grouped by merchant, with a suggestion where the app has one."><UncategorizedSheet total={review.uncategorized} locale={locale} /></SummaryCard> }] : [],
56	    ...recurring.length > 0 ? [{ key: "recurring", node: <SummaryCard title={`${plural(recurring.length, "recurring change", "recurring changes")} to confirm`} detail="Payments that repeat, and price changes on ones you confirmed."><RecurringSheet proposals={recurring} /></SummaryCard> }] : [],
57	    ...review.findings.length > 0 ? [{ key: "findings", node: <SummaryCard title={`${plural(review.findings.length, "thing looks", "things look")} off`} detail="Possible duplicates, fees and unusual charges from your latest syncs."><FindingsSheet findings={review.findings} locale={locale} /></SummaryCard> }] : [],
58	    ...groupRepeats(proposals).map(group => ({ key: group[0].id, filter: filterOf(group[0].kind), node: group.length === 1 ? <IouCard id={group[0].id} initial={group[0]} locale={locale} /> : <RepeatGroup proposals={group} locale={locale} /> })),
59	  ];
60	  const count = filter ? entries.filter(entry => entry.filter === filter).length : entries.length;
61	  const present = FILTERS.filter(([key]) => proposals.some(proposal => filterOf(proposal.kind) === key));
62	  const chip = (active: boolean) => `h-11 rounded-full border px-3.5 lg:h-9 text-[13px] transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ai ${active ? "border-foreground bg-foreground text-background" : "border-input text-muted-foreground hover:bg-muted hover:text-foreground"}`;
63	  return <details open aria-label="Waiting for you" className="group">
64	    <summary className="-mx-1 flex min-h-11 cursor-pointer list-none items-center gap-2.5 rounded-lg px-1 focus-visible:outline-2 focus-visible:outline-ai [&::-webkit-details-marker]:hidden">
65	      <span className="font-display text-lg font-semibold">Waiting for you</span>
66	      <span className="rounded-full bg-ai-soft px-2 py-0.5 text-xs font-medium text-ai tabular-nums">{count}<span className="sr-only"> {count === 1 ? "decision" : "decisions"}</span></span>
67	      <ChevronDown className="ml-auto size-4 text-muted-foreground transition-transform group-not-open:-rotate-90" aria-hidden="true" />
68	    </summary>
69	    {present.length > 1 && <div role="group" aria-label="Show" className="mt-2 flex flex-wrap gap-1.5">
70	      <button type="button" aria-pressed={!filter} onClick={() => setFilter(undefined)} className={chip(!filter)}>All</button>
71	      {present.map(([key, label]) => <button key={key} type="button" aria-pressed={filter === key} onClick={() => setFilter(key)} className={chip(filter === key)}>{label}</button>)}
72	    </div>}
73	    {entries.map((entry, index) => <div key={entry.key} hidden={filter ? entry.filter !== filter : !expanded && index >= VISIBLE}>{entry.node}</div>)}
74	    {!filter && entries.length > VISIBLE && <button type="button" aria-expanded={expanded} onClick={() => setExpanded(open => !open)} className="mt-1 min-h-11 text-sm font-medium text-ai underline-offset-2 hover:underline lg:min-h-9">{expanded ? "Show fewer" : `View all ${entries.length}`}</button>}
75	  </details>;
76	}
