1	import { z } from "zod";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	import { answerQuestion, setMemory } from "@/lib/organize/owner";
4	import { SOURCES, SOURCE_LABEL, loadDecisions, loadMemory, loadNames, loadOpenQuestions } from "@/lib/organize/surfaces";
5	import { formatMoney } from "@/lib/finance/format";
6	
7	type Context = { supabase: SupabaseClient; workspace: { id: string; timezone: string; locale: string }; chatRequestId?: string };
8	
9	export const organizeReviewSchema = z.object({
10	  view: z.enum(["questions", "decisions", "memory"]).describe("questions: what the organizer is asking the owner; decisions: rows it, a rule, a confirmed payee or the bank's data labelled; memory: what the owner told it each payee is"),
11	  source: z.enum(SOURCES).optional().describe("decisions only: who labelled the rows"),
12	}).strict();
13	
14	export async function organizeReview({ supabase, workspace }: Context, input: z.infer<typeof organizeReviewSchema>) {
15	  const names = await loadNames(supabase, workspace.id);
16	  if (input.view === "questions") {
17	    const questions = await loadOpenQuestions(supabase, workspace.id, 20, 4);
18	    return { questions: questions.map(item => ({ questionId: item.id, identityId: item.identityId, payee: item.identityName, question: item.question, rows: item.transactionIds.length, stillBlank: item.blank,
19	      examples: item.rows.map(row => ({ id: row.id, date: row.posted_on, description: row.description, amountFormatted: formatMoney(row.amount_minor, row.currency_code, workspace.locale) })) })) };
20	  }
21	  if (input.view === "memory") {
22	    const memory = await loadMemory(supabase, workspace.id);
23	    return { memory: memory.slice(0, 50).map(item => ({ memoryId: item.id, identityId: item.identityId, payee: item.identityName, category: item.categoryId && names.categories.get(item.categoryId), merchant: item.merchantId && names.merchants.get(item.merchantId),
24	      purpose: item.purpose, saidBy: item.source === "owner" ? "owner" : "organizer", rows: item.covered })) };
25	  }
26	  const { decisions, total } = await loadDecisions(supabase, workspace.id, { source: input.source, pageSize: 30 });
27	  return { total, showing: decisions.length, decisions: decisions.map(row => ({ id: row.id, date: row.posted_on, description: row.description, amountFormatted: formatMoney(row.amount_minor, row.currency_code, workspace.locale),
28	    category: row.category_id && names.categories.get(row.category_id), merchant: row.merchant_id && names.merchants.get(row.merchant_id), decidedBy: SOURCE_LABEL[row.source], confidence: row.ai_confidence, reason: row.ai_reason })) };
29	}
30	
31	export const organizeInputSchema = z.object({
32	  questionId: z.uuid().optional().describe("An open question's id from organize_review"),
33	  identityId: z.uuid().optional().describe("The payee's id from organize_review; needed only without a questionId"),
34	  category: z.string().trim().min(1).max(100).optional().describe("An existing category's name"),
35	  merchant: z.string().trim().min(1).max(100).optional().describe("An existing merchant's name"),
36	}).strict().refine(input => input.questionId || input.identityId, "Give the question or the payee").refine(input => input.category || input.merchant, "Give a category or a merchant");
37	
38	export const organizeAnswerSchema = z.object({ questionId: z.uuid().nullable(), identityId: z.uuid(), categoryId: z.uuid().nullable(), merchantId: z.uuid().nullable() }).strict();
39	
40	const named = <T extends { id: string; name: string }>(list: T[], text: string | undefined, what: string) => {
41	  if (!text) return null;
42	  const match = list.find(item => item.name.toLocaleLowerCase("en") === text.toLocaleLowerCase("en"));
43	  if (!match) throw new Error(`There is no ${what} called "${text}". Only existing ones can be used; tell the owner to add it first.`);
44	  return match;
45	};
46	
47	export async function proposeOrganizeAnswer({ supabase, workspace, chatRequestId }: Context, input: z.infer<typeof organizeInputSchema>) {
48	  const [names, open] = await Promise.all([loadNames(supabase, workspace.id), input.questionId
49	    ? supabase.from("organize_questions").select("id, identity_id, transaction_ids").eq("workspace_id", workspace.id).eq("status", "open").eq("id", input.questionId)
50	    : supabase.from("organize_questions").select("id, identity_id, transaction_ids").eq("workspace_id", workspace.id).eq("status", "open").eq("identity_id", input.identityId!)]);
51	  if (open.error) throw new Error(open.error.message);
52	  const question = open.data?.[0] as { id: string; identity_id: string | null; transaction_ids: string[] } | undefined;
53	  if (input.questionId && !question) throw new Error("That question is not open any more");
54	  const identityId = question?.identity_id ?? input.identityId;
55	  if (!identityId) throw new Error("This question has no payee yet, so give the payee's identityId or have the owner label its rows in Transactions");
56	  const identity = await supabase.from("organize_identities").select("display_name").eq("workspace_id", workspace.id).eq("id", identityId).maybeSingle();
57	  if (identity.error || !identity.data) throw new Error("Payee not found");
58	  const category = named(names.categoryList, input.category, "category"), merchant = named(names.merchantList, input.merchant, "merchant");
59	  const payload = organizeAnswerSchema.parse({ questionId: question?.id ?? null, identityId, categoryId: category?.id ?? null, merchantId: merchant?.id ?? null });
60	  const who = String(identity.data.display_name);
61	  const title = `Label ${who} as ${[category?.name, merchant?.name].filter(Boolean).join(" · ")}`.slice(0, 200);
62	  const detail = `Applies to its rows that are blank or labelled by the AI${question ? `, ${question.transaction_ids.length} in this question` : ""}, and is remembered for its future payments.`;
63	  const { data, error } = await supabase.from("agent_proposals").insert({ workspace_id: workspace.id, agent: "chat", kind: "organize_answer", ...(chatRequestId ? { chat_request_id: chatRequestId } : {}),
64	    conflict_key: `organize_answer:${crypto.randomUUID()}`, title, detail, payload, confidence: 100 }).select("id").single();
65	  if (error) throw new Error(error.message);
66	  return { proposalId: data.id as string, title };
67	}
68	
69	export async function applyOrganizeAnswer({ supabase }: Context, payload: unknown) {
70	  const parsed = organizeAnswerSchema.parse(payload);
71	  if (parsed.questionId) await answerQuestion(supabase, { questionId: parsed.questionId, identityId: parsed.identityId, categoryId: parsed.categoryId, merchantId: parsed.merchantId });
72	  else await setMemory(supabase, { identityId: parsed.identityId, categoryId: parsed.categoryId, merchantId: parsed.merchantId, applyToExisting: true });
73	  return { href: "/money/organize", undo: parsed.questionId ? "Undo from AI organizer → Needs you" : "Undo from the transactions" };
74	}
