144	      detail: `${SOURCE[decision.source]}: ${decision.reason}. Applied automatically${decision.source === "ai" ? " as an AI label" : ""}, without saving a rule; Undo restores every row.`,
145	      evidence: { facts: [{ label: "Rows", value: String(chunk.length) }, { label: "Decided by", value: SOURCE[decision.source] }, { label: "Reason", value: decision.reason }],
146	        transactions: chunk.slice(0, 5).map(row => ({ id: row.id, date: row.date, description: row.description.slice(0, 120), amountMinor: row.amountMinor.toString(), currency: row.currency })),
147	        links: [{ label: "Organization", href: "/money/organization" }] },
148	      payload: { rows: chunk.map(row => ({ id: row.id, version: row.version })),
149	        patch: { ...(decision.merchantId ? { merchant_id: decision.merchantId } : {}), ...(decision.categoryId ? { category_id: decision.categoryId } : {}) },
150	        merchantName: decision.merchantId ? null : decision.merchantName, ruleKey: null, evidence: [], identityKey: item.key.slice(0, 1000), source: decision.source },
151	      confidence: decision.confidence, notes: [] });
152	  }
153	  return proposals;
154	}
