174	  const pausedUntil = previous?.organize_after && Date.parse(previous.organize_after) > Date.now() ? previous.organize_after : null;
175	  const model = run.model_status === "available" && !pausedUntil ? await modelForSettings(context.settings, "agents").catch(() => null) : null;
176	  const ask: Ask | null = model && (async request => {
177	    try { await activeRun(db, runId, workspace.id); } catch (error) { if (error instanceof RunInactive) throw new StopWork("The run was stopped"); throw error; }
178	    if (!checked(await db.rpc("reserve_agent_model_call", { p_run_id: runId, p_workspace_id: workspace.id }))) throw new StopWork("The model budget for this run is spent");
179	    return askModel(model, request);
180	  });
181	  const result = await organize(input, ask, { onPlan: async batches => {
182	    const current = checked(await db.from("agent_runs").select("model_calls, model_budget").eq("id", runId).eq("workspace_id", workspace.id).single()) as { model_calls: number; model_budget: number };
183	    checked(await db.from("agent_runs").update({ model_budget: Math.min(MODEL_BUDGET_CEILING, Math.max(current.model_budget, current.model_calls + batches * 2 + 1)) }).eq("id", runId).eq("workspace_id", workspace.id));
184	    await report(context, { type: "step", text: `Asking the AI about the rest in ${plural(batches, "batch", "batches")}, one decision per payee` });
185	  } });
186	  await activeRun(db, runId, workspace.id);
187	  const resumes = pausedUntil && new Date(pausedUntil).toLocaleTimeString(workspace.locale, { timeZone: workspace.timezone, hour: "2-digit", minute: "2-digit" });
188	  if (!ask && result.left.length) await report(context, { type: "note", text: pausedUntil ? `The AI hit its limit in an earlier run and is asked again at ${resumes}; ${plural(result.left.length, "row")} wait until then`
189	    : `No AI available; ${plural(result.left.length, "row")} the bank's data and your rules couldn't decide wait for the next run` });
190	  if (result.stopped) await report(context, { type: "note", text: `${result.stopped instanceof StopWork ? result.stopped.message : "The AI plan's usage limit was reached"}; ${plural(result.left.length, "row")} wait for the next run` });
191	  const retryAt = !result.left.length ? null : pausedUntil ?? (ask ? new Date(retryLeftoversAt(result.stopped, Date.now())).toISOString() : null);
192	  if (retryAt) checked(await db.from("agent_runs").update({ organize_after: retryAt }).eq("id", runId).eq("workspace_id", workspace.id));
193	  for (const failure of result.failed.slice(0, 3)) await report(context, { type: "note", text: `The AI failed on ${plural(failure.rows.length, "row")} (${failure.error instanceof Error ? failure.error.message : String(failure.error)}); they wait for the next run` });
194	
195	  const labels: Decided[] = [], asking: Decided[] = [];
196	  for (const item of result.decided) {
197	    const level = item.decision.kind === "label" ? aiConfidence(item.decision.confidence) : "low";
198	    const applies = item.decision.kind === "label" && (item.decision.source !== "ai" || level === "high" || (level === "medium" && calibrated.mediumAllowed));
199	    (applies ? labels : asking).push(item);
200	  }
201	  const unplaced = new Set(await withNewCategories(context, input.categories, labels.map(item => item.decision as Label)));
202	  asking.push(...labels.filter(item => unplaced.has(item.decision as Label)));
203	  const applied = labels.filter(item => !unplaced.has(item.decision as Label));
204	  let raised = 0;
205	  for (const item of asking) {
206	    const { error } = await db.rpc("raise_organize_question", { p_workspace: workspace.id, p_identity_key: item.key.slice(0, 1000), p_identity_id: item.identity?.id ?? null,
207	      p_question: questionText(item, input), p_transaction_ids: item.rows.slice(0, 500).map(row => row.id), p_created_by: "ai" });
208	    if (error) await report(context, { type: "note", text: `A question could not be saved: ${error.message}` }); else raised++;
209	  }
210	  const proposals = applied.flatMap((item, index) => organizeProposals(item, index, input));
211	  const own = rowCount(applied.filter(item => (item.decision as Label).source !== "ai"));
212	  const left = result.left.length + rowCount(result.failed);
213	  return { proposals, summary: `${plural(input.rows.length, "row")} read: ${rowCount(applied)} labelled (${own} from your rules, memory and the bank's data), ${rowCount(asking)} in ${plural(raised, "question")} for you${left ? `, ${left} left for the next run` : ""}; ${plural(result.calls, "AI call")}` };
214	}
