119	export function uncertainPairs(rows: TransferCandidate[]) {
120	  const outsider = (row: TransferCandidate) => !!row.raw && (OUTSIDE.has(row.raw.payment_type) || row.raw.payment_type === "exchange" || !!row.raw.counterparty_iban || !!row.raw.creditor_id);
121	  const open = rows.filter(row => !outsider(row));
122	  const matches = (out: TransferCandidate, into: TransferCandidate) => out.amountMinor < 0n && into.amountMinor === -out.amountMinor && out.currencyCode === into.currencyCode
123	    && out.accountId !== into.accountId && days(out.postedOn, into.postedOn) <= MATCH_DAYS;
124	  return open.flatMap(out => {
125	    const ins = open.filter(into => matches(out, into));
126	    return ins.length === 1 && open.filter(other => matches(other, ins[0])).length === 1 ? [{ outId: out.id, inId: ins[0].id }] : [];
127	  });
128	}
