130	export function internalMoves(rows: TransferCandidate[]) {
131	  const groups = new Map<string, TransferCandidate[]>();
132	  for (const row of rows) {
133	    const key = organizationDescriptionKey(row.text ?? "");
134	    if (!isInternalMove(row.raw) || key.length < 3) continue;
135	    groups.set(key, [...groups.get(key) ?? [], row]);
136	  }
137	  const bothWays = (items: TransferCandidate[]) => items.some(a => a.amountMinor < 0n && items.some(b => b.amountMinor > 0n && b.accountId === a.accountId));
138	  return [...groups].filter(([, items]) => bothWays(items) || items.some(item => ["transfer", "top_up"].includes(item.raw!.payment_type)))
139	    .map(([key, items]) => {
140	      const identities = new Set(items.map(item => item.identityId ?? null));
141	      return { key, transactionIds: items.map(item => item.id).sort().slice(0, 500), identityId: identities.size === 1 ? [...identities][0] : null };
142	    }).sort((a, b) => a.key.localeCompare(b.key));
143	}
