4	const rpc = async <T,>(db: SupabaseClient, name: string, args: Record<string, unknown>, schema: z.ZodType<T>): Promise<T> => {
5	  const { data, error } = await db.rpc(name, args);
6	  if (error) throw new Error(error.message);
7	  return schema.parse(data);
8	};
9	const confirmed = z.object({ memoryId: z.uuid(), batchId: z.uuid().nullable(), applied: z.number().int() });
10	const nothing = z.unknown();
11	
12	export const setMemory = (db: SupabaseClient, input: { identityId: string; categoryId: string | null; merchantId: string | null; purpose?: string | null; applyToExisting: boolean }) =>
13	  rpc(db, "confirm_organize_memory", { p_identity: input.identityId, p_category: input.categoryId, p_merchant: input.merchantId, p_apply_to_existing: input.applyToExisting, p_purpose: input.purpose ?? null }, confirmed);
14	
15	export async function answerQuestion(db: SupabaseClient, input: { questionId: string; identityId: string; categoryId: string | null; merchantId: string | null }) {
16	  const result = await setMemory(db, { ...input, applyToExisting: true });
17	  await rpc(db, "answer_organize_question", { p_question: input.questionId, p_status: "answered",
18	    p_answer: { categoryId: input.categoryId, merchantId: input.merchantId, memoryId: result.memoryId, batchId: result.batchId, applied: result.applied } }, nothing);
19	  return result;
20	}
