25	
26	const undoResult = z.object({ undone: z.number().int(), skipped: z.number().int() });
27	export const undoLabels = (db: SupabaseClient, opIds: string[]) => rpc(db, "undo_ai_organization", { p_op_ids: opIds }, undoResult);
28	
29	export const confirmLabels = (db: SupabaseClient, transactionIds: string[]) => rpc(db, "confirm_ai_organization", { p_transaction_ids: transactionIds }, z.number().int());
