31	export async function undoAnswer(db: SupabaseClient, workspaceId: string, batchId: string) {
32	  const batch = await db.from("transaction_batches").select("selection").eq("workspace_id", workspaceId).eq("id", batchId).maybeSingle();
33	  if (batch.error || !batch.data) throw new Error("This answer was not found");
34	  const ids = z.array(z.object({ id: z.uuid() })).parse(batch.data.selection).map(row => row.id);
35	  const current = await db.from("transactions").select("id, version").eq("workspace_id", workspaceId).in("id", ids);
36	  if (current.error) throw new Error(current.error.message);
37	  if ((current.data ?? []).length !== ids.length) throw new Error("Some of these rows no longer exist, so the answer cannot be undone as a whole");
38	  const { error } = await db.rpc("undo_transaction_batch", { p_batch_id: batchId, p_rows: current.data });
39	  if (error) throw new Error(error.message);
40	}
